    delete from classroom_blocks where lesson_id = v_lesson;
  end if;
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'text', $blk${"html": "<p><img src=\"https://classroom.wowteach.ru/media/shared/gg/hello_teen_wave.webp\" alt=\"\" style=\"height:200px\"></p><h2>Unit 8 · A happy life</h2><p>Сегодня — о планах на жизнь: кем быть, что иметь, чему научиться и где жить.</p>"}$blk$::jsonb, 0);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'flashcards', $blk${"title": "Повторяем слова урока. Нажми на карточку — услышишь слово и увидишь перевод", "cards": [{"text": "be rich", "translation": "быть богатым", "audio": "", "audio_tts": {"text": "be rich.", "voice": "en_GB-alba"}}, {"text": "be famous", "translation": "быть знаменитым", "audio": "", "audio_tts": {"text": "be famous.", "voice": "en_GB-alba"}}, {"text": "be a doctor", "translation": "быть врачом", "audio": "", "audio_tts": {"text": "be a doctor.", "voice": "en_GB-alba"}}, {"text": "be an astronaut", "translation": "быть космонавтом", "audio": "", "audio_tts": {"text": "be an astronaut.", "voice": "en_GB-alba"}}, {"text": "have my own business", "translation": "иметь своё дело", "audio": "", "audio_tts": {"text": "have my own business.", "voice": "en_GB-alba"}}, {"text": "have an interesting job", "translation": "иметь интересную работу", "audio": "", "audio_tts": {"text": "have an interesting job.", "voice": "en_GB-alba"}}, {"text": "have a big family", "translation": "иметь большую семью", "audio": "", "audio_tts": {"text": "have a big family.", "voice": "en_GB-alba"}}, {"text": "have good health", "translation": "быть здоровым", "audio": "", "audio_tts": {"text": "have good health.", "voice": "en_GB-alba"}}, {"text": "learn a foreign language", "translation": "выучить иностранный язык", "audio": "", "audio_tts": {"text": "learn a foreign language.", "voice": "en_GB-alba"}}, {"text": "learn to drive", "translation": "научиться водить машину", "audio": "", "audio_tts": {"text": "learn to drive.", "voice": "en_GB-alba"}}, {"text": "live abroad", "translation": "жить за границей", "audio": "", "audio_tts": {"text": "live abroad.", "voice": "en_GB-alba"}}, {"text": "live on my own", "translation": "жить самостоятельно", "audio": "", "audio_tts": {"text": "live on my own.", "voice": "en_GB-alba"}}, {"text": "ambition", "translation": "мечта, цель в жизни", "audio": "", "audio_tts": {"text": "ambition.", "voice": "en_GB-alba"}}]}$blk$::jsonb, 1);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'match', $blk${"title": "Соедини начало и конец предложения — получатся мечты Гэри", "pairs": [{"left": "I want to be", "right": "rich."}, {"left": "I'd like to have my", "right": "own business."}, {"left": "I don't want to live on", "right": "my own."}, {"left": "I want to learn to", "right": "drive when I'm 18."}, {"left": "I'd love to have", "right": "a big family."}]}$blk$::jsonb, 2);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'sort', $blk${"title": "Распредели мечты по глаголам", "groups": [{"name": "be …", "items": [{"text": "rich"}, {"text": "famous"}, {"text": "a doctor"}]}, {"name": "have …", "items": [{"text": "my own business"}, {"text": "an interesting job"}, {"text": "a big family"}]}, {"name": "learn …", "items": [{"text": "a foreign language"}, {"text": "to drive"}]}, {"name": "live …", "items": [{"text": "abroad"}, {"text": "on my own"}]}]}$blk$::jsonb, 3);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'gaps', $blk${"title": "Прочитай про семью Гэри и перетащи слова в пропуски", "mode": "drag", "text": "When Gary's mum, Karen, was seventeen, she wanted to be __famous__ and sing in a band.\nWhen his dad, Steve, was at school, he wanted to leave England one day and to live __abroad__. He went to the USA.\nHis little brother, Kenny, would like to be a __doctor__. He practises on his toys.\nGary's sister, Tracy, wants to have an __interesting job__. She'd love to be an astronaut.\nFinally, his cousin, Nadia, would like to learn a __foreign language__, but she can't decide which to choose."}$blk$::jsonb, 4);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'gaps', $blk${"title": "Прочитай историю про клоуна Фреда и впиши по одному слову", "mode": "type", "text": "When Funny Fred left school, he wanted to __be__ a clown and to have his __own__ business. He decided to leave the UK and to live __abroad__ – he moved to the USA. What did he do there? He went to circus school to __learn__ about acrobatics and magic tricks. He also learned to play __the__ drums. When he finished school, he learned two __foreign__ languages – French and Italian. Then he opened his own circus schools in the UK, France and Italy. Now he has a big business. Funny Fred often visits children's hospitals too. He wears his clown clothes because he wants the children to __have__ fun and get better quickly!"}$blk$::jsonb, 5);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'speaking', $blk${"title": "SPEAKING 🎤 Расскажи вслух и запиши ответ", "needs_review": true, "html": "<p>Расскажи о своих планах на будущее: кем ты хочешь стать, что хотел бы иметь, чему научиться и где жить. Четыре-пять предложений.</p>", "sample": "", "sample_tts": {"text": "I want to learn to drive.", "voice": "en_GB-alba"}}$blk$::jsonb, 6);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'text', $blk${"html": "<p><img src=\"https://classroom.wowteach.ru/media/shared/gg/bye_star.webp\" alt=\"\" style=\"height:200px\"></p><p>Готово. Теперь ты можешь рассказать о своих планах по-английски.</p>"}$blk$::jsonb, 7);
end $$;

do $$
declare v_lesson uuid;
begin
  select id into v_lesson from classroom_lessons
   where unit_id = '028f1e92-6608-40c6-befc-4395319ab6ea' and title = 'Homework 2';
  if v_lesson is null then
    insert into classroom_lessons (unit_id, title, sort_order, kind, is_published)
    values ('028f1e92-6608-40c6-befc-4395319ab6ea', 'Homework 2', 1, 'homework', false) returning id into v_lesson;
  else
    update classroom_lessons set sort_order = 1, kind = 'homework' where id = v_lesson;
    delete from classroom_blocks where lesson_id = v_lesson;
  end if;
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'text', $blk${"html": "<p><img src=\"https://classroom.wowteach.ru/media/shared/gg/hello_girl_wave.webp\" alt=\"\" style=\"height:200px\"></p><h2>Unit 8 · will — предсказания</h2><p>Сегодня — как говорить о будущем: will и won’t.</p>"}$blk$::jsonb, 0);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'match', $blk${"title": "Соедини факт с предсказанием", "pairs": [{"left": "I love music.", "right": "I'll be a famous musician one day."}, {"left": "We are mad about bikes.", "right": "We'll ride around Europe one day."}, {"left": "Maggie likes the city.", "right": "She'll live in her own flat in the centre one day."}, {"left": "Bob and Sam can cook very well.", "right": "They'll open a restaurant one day."}]}$blk$::jsonb, 1);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'quiz', $blk${"title": "Прочитай предсказания Эммы и выбери правильную форму", "questions": [{"q": "I love going abroad, so when I'm older, I ___ travel a lot.", "type": "single", "correct": [0], "options": [{"text": "will"}, {"text": "won't"}]}, {"q": "I only speak English and a bit of German, so I think I ___ learn another foreign language.", "type": "single", "correct": [0], "options": [{"text": "will"}, {"text": "won't"}]}, {"q": "My dream is to visit the Amazon rainforest. My cousin George says he hopes that he ___ go there with me.", "type": "single", "correct": [0], "options": [{"text": "will"}, {"text": "won't"}]}, {"q": "But I don't like spiders, so maybe I ___ go to the Amazon!", "type": "single", "correct": [1], "options": [{"text": "will"}, {"text": "won't"}]}, {"q": "I actually think George ___ travel with me …", "type": "single", "correct": [1], "options": [{"text": "will"}, {"text": "won't"}]}, {"q": "… because he ___ prefer to play computer games every day with Harry!", "type": "single", "correct": [0], "options": [{"text": "will"}, {"text": "won't"}]}]}$blk$::jsonb, 2);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'order', $blk${"title": "Составь предсказания о будущем этих ребят", "items": [{"words": ["Maria", "will", "play", "football", "for", "England."], "sentence": "Maria will play football for England.", "prompt": "Мария отлично играет в футбол"}, {"words": ["Tanya", "will", "be", "a", "French", "teacher."], "sentence": "Tanya will be a French teacher.", "prompt": "Таня учит французский и любит объяснять"}, {"words": ["Gary", "will", "be", "a", "vet."], "sentence": "Gary will be a vet.", "prompt": "Гэри возится с собаками и кошками"}, {"words": ["Denise", "will", "buy", "a", "cottage."], "sentence": "Denise will buy a cottage.", "prompt": "Дениз мечтает о домике за городом"}, {"words": ["Mark", "will", "learn", "to", "drive", "a", "car."], "sentence": "Mark will learn to drive a car.", "prompt": "Марку скоро восемнадцать"}]}$blk$::jsonb, 3);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'order', $blk${"title": "Составь вопросы о будущем", "items": [{"words": ["Will", "Donald", "visit", "China?"], "sentence": "Will Donald visit China?", "prompt": "Дональд поедет в Китай?"}, {"words": ["Will", "Greg", "and", "Tony", "win", "lots", "of", "money?"], "sentence": "Will Greg and Tony win lots of money?", "prompt": "Грег и Тони выиграют много денег?"}, {"words": ["Will", "I", "be", "an", "amazing", "singer?"], "sentence": "Will I be an amazing singer?", "prompt": "я стану прекрасным певцом?"}, {"words": ["Will", "we", "all", "be", "happy?"], "sentence": "Will we all be happy?", "prompt": "мы все будем счастливы?"}]}$blk$::jsonb, 4);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'gaps', $blk${"title": "Впиши короткий ответ: ✔ — да, ✘ — нет", "mode": "type", "text": "Will Susan be famous? ✔ Yes, __she will__.\nWill Donald visit China? ✘ No, __he won't__.\nWill Greg and Tony win lots of money? ✘ No, __they won't__.\nWill I be an amazing singer? ✔ Yes, __you will__.\nWill we all be happy? ✔ Yes, __we will__."}$blk$::jsonb, 5);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'task', $blk${"title": "WRITING ✍️ Напиши о своём будущем", "needs_review": true, "html": "<p>Составь из слов два вопроса и ответь на них правдиво.</p><ol><li>be / will / What / you / ?</li><li>live / will / you / Where / ?</li></ol><p>Потом добавь ещё три своих предсказания с <b>will</b> и <b>won’t</b>.</p>"}$blk$::jsonb, 6);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'text', $blk${"html": "<p><img src=\"https://classroom.wowteach.ru/media/shared/gg/bye_trophy.webp\" alt=\"\" style=\"height:200px\"></p><p>Будущее время разобрано: will — будет, won’t — не будет.</p>"}$blk$::jsonb, 7);
end $$;

do $$
declare v_lesson uuid;
begin
  select id into v_lesson from classroom_lessons
   where unit_id = '028f1e92-6608-40c6-befc-4395319ab6ea' and title = 'Homework 3';
  if v_lesson is null then
    insert into classroom_lessons (unit_id, title, sort_order, kind, is_published)
    values ('028f1e92-6608-40c6-befc-4395319ab6ea', 'Homework 3', 2, 'homework', false) returning id into v_lesson;
  else
    update classroom_lessons set sort_order = 2, kind = 'homework' where id = v_lesson;
    delete from classroom_blocks where lesson_id = v_lesson;
  end if;
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'text', $blk${"html": "<p><img src=\"https://classroom.wowteach.ru/media/shared/gg/hello_highfive.webp\" alt=\"\" style=\"height:200px\"></p><h2>Unit 8 · Вопросы и вопросительные слова</h2><p>Сегодня — как спросить про что угодно: What, Where, When, Who, Why, How often.</p>"}$blk$::jsonb, 0);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'match', $blk${"title": "Соедини начало и конец предложения — получится история про доктора Кью", "pairs": [{"left": "Doctor Q invited his", "right": "mum to stay."}, {"left": "Doctor Q called her", "right": "on the phone."}, {"left": "Mrs Q visited him", "right": "two days later."}, {"left": "Mrs Q didn't want to shake", "right": "hands."}, {"left": "Mrs Q gave everyone", "right": "a hug."}, {"left": "Pi didn't", "right": "kiss her."}]}$blk$::jsonb, 1);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'gaps', $blk${"title": "Прочитай разговор миссис Кью с сыном и перетащи слова в пропуски", "mode": "drag", "text": "Mrs Q: __How often__ do you exercise, Cornelius?\nDr Q: Not very often, Mum.\nMrs Q: __What__ time did you get up?\nDr Q: At 5.30, Mum!\nMrs Q: __Why__ are you tired?\nDr Q: Because we went for a long run in the morning!\nMrs Q: __Where__ are we going after lunch?\nDr Q: To my lab!\nMrs Q: __Who__ are you calling?\nDr Q: I'm calling Dr Spark. He's my friend. He's visiting me today.\nMrs Q: __When__ is he visiting?\nDr Q: At four o'clock."}$blk$::jsonb, 2);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'quiz', $blk${"title": "Прочитай ответ и выбери вопрос, который к нему подходит", "questions": [{"q": "B: EMILY invited us to stay.", "type": "single", "correct": [0], "options": [{"text": "Who invited us to stay?"}, {"text": "Who did we invite to stay?"}]}, {"q": "B: Poppy visited GEORGE yesterday.", "type": "single", "correct": [1], "options": [{"text": "Who visited Poppy yesterday?"}, {"text": "Who did Poppy visit yesterday?"}]}, {"q": "B: FRED saw them at the park.", "type": "single", "correct": [0], "options": [{"text": "Who saw them at the park?"}, {"text": "Who did they see at the park?"}]}, {"q": "B: Grandma kissed SOPHIE.", "type": "single", "correct": [1], "options": [{"text": "Who kissed Grandma?"}, {"text": "Who did Grandma kiss?"}]}]}$blk$::jsonb, 3);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'order', $blk${"title": "Составь вопрос к ответу", "items": [{"words": ["What", "do", "you", "want", "to", "do?"], "sentence": "What do you want to do?", "prompt": "B: I want to play football."}, {"words": ["Who", "are", "you", "calling?"], "sentence": "Who are you calling?", "prompt": "B: I'm calling my grandma."}, {"words": ["When", "did", "they", "arrive?"], "sentence": "When did they arrive?", "prompt": "B: They arrived two hours ago."}, {"words": ["Where", "will", "you", "live?"], "sentence": "Where will you live?", "prompt": "B: I'll live in Berlin."}]}$blk$::jsonb, 4);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'gaps', $blk${"title": "Прочитай разговор Кейт и Сьюзи и впиши по одному слову", "mode": "type", "text": "Kate: This is great ice cream. Who __brought__ it?\nSusie: My aunt brought it. She's staying here for the weekend.\nKate: How __often__ __does__ she visit you?\nSusie: Every holiday. She's a teacher.\nKate: __What__ does she __teach__?\nSusie: She teaches Music. I'm going to stay at her house in the summer.\nKate: __Where__ does __she__ live?\nSusie: In Scotland. You should come to visit too! __When__ __are__ you going on holiday with your parents? We can visit her before your holiday.\nKate: We're going in August, so I'm free in July.\nAunt: Hi there, Susie. __Who__ __did__ you invite to stay at my house?\nSusie: Oh, hi, Aunt Maria. This is Kate. I invited her, she's my best friend."}$blk$::jsonb, 5);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'speaking', $blk${"title": "SPEAKING 🎤 Задай вопросы и запиши ответ", "needs_review": true, "html": "<p>Представь, что в класс пришёл новый ученик. Задай ему пять вопросов с разными словами: What, Where, When, Who, How often.</p>", "sample": "", "sample_tts": {"text": "How often do you play computer games?", "voice": "en_GB-alba"}}$blk$::jsonb, 6);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'text', $blk${"html": "<p><img src=\"https://classroom.wowteach.ru/media/shared/gg/bye_medal.webp\" alt=\"\" style=\"height:200px\"></p><p>Вопросы разобраны: и обычные, и те, где спрашивают про подлежащее.</p>"}$blk$::jsonb, 7);
end $$;

do $$
declare v_lesson uuid;
begin
  select id into v_lesson from classroom_lessons
   where unit_id = '028f1e92-6608-40c6-befc-4395319ab6ea' and title = 'Homework 4';
  if v_lesson is null then
    insert into classroom_lessons (unit_id, title, sort_order, kind, is_published)
    values ('028f1e92-6608-40c6-befc-4395319ab6ea', 'Homework 4', 3, 'homework', false) returning id into v_lesson;
  else
    update classroom_lessons set sort_order = 3, kind = 'homework' where id = v_lesson;
    delete from classroom_blocks where lesson_id = v_lesson;
  end if;
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'text', $blk${"html": "<p><img src=\"https://classroom.wowteach.ru/media/shared/gg/hello_teen_wave.webp\" alt=\"\" style=\"height:200px\"></p><h2>Unit 8 · Согласие и несогласие</h2><p>Сегодня — как сказать по-английски «я согласен» и «я так не думаю».</p>"}$blk$::jsonb, 0);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'sort', $blk${"title": "Распредели фразы на согласие и несогласие", "groups": [{"name": "✅ согласие", "items": [{"text": "I agree with you."}, {"text": "You're right."}, {"text": "That's true."}, {"text": "That's what I think too."}]}, {"name": "❌ несогласие", "items": [{"text": "I disagree with you."}, {"text": "You're wrong."}, {"text": "That's not true."}, {"text": "I don't think so."}]}]}$blk$::jsonb, 1);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'quiz', $blk${"title": "Прочитай реплику и выбери подходящий ответ", "questions": [{"q": "A: Everybody likes summer holidays.", "type": "single", "correct": [2], "options": [{"text": "That's true. It's a brilliant idea."}, {"text": "I agree. She likes them."}, {"text": "You're right. They're fun."}]}, {"q": "A: History is boring.", "type": "single", "correct": [1], "options": [{"text": "No, that isn't right. We have Maths now."}, {"text": "I disagree with you. I think it's interesting."}, {"text": "I don't think so. He's clever."}]}, {"q": "A: The violin is a difficult instrument to play.", "type": "single", "correct": [0], "options": [{"text": "That's true. The piano is easier."}, {"text": "That isn't true. It's difficult."}, {"text": "That's what I think. It's amazing."}]}]}$blk$::jsonb, 2);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'gaps', $blk${"title": "Прочитай разговор Ника с папой и перетащи слова в пропуски", "mode": "drag", "text": "Dad: OK, the carpet is clean now. Good job, Nick. Are you tired?\nNick: No, I'm not tired, I'm bored. Chores are boring!\nDad: I agree __with__ you. Let's go shopping. All kids like shopping.\nNick: That's not __true__. I hate shopping. Shopping is boring too.\nDad: I __don't__ agree with you. It was fun at the tech shop last week.\nNick: You're __right__. That's an amazing shop.\nDad: That's __what__ I think too.\nNick: Let's go by bus. It's quicker than the tram.\nDad: I don't think __so__. The bus is really slow!\nNick: OK. I'll be ready in five minutes."}$blk$::jsonb, 3);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'gaps', $blk${"title": "Впиши по одному слову в ответы", "mode": "type", "text": "A: Everybody loves pizza.\nB: I __agree__! I often have pizza because it's tasty.\nA: Everybody hates tests.\nB: __You're__ __right__. I don't like them because they're sometimes difficult.\nA: Girls don't want to be pilots.\nB: I disagree __with__ __you__. Girls want to be pilots because it's an exciting job.\nA: Kids don't like climbing.\nB: __That's__ not __true__. They love climbing because it's fun."}$blk$::jsonb, 4);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'task', $blk${"title": "WRITING ✍️ Напиши своё мнение", "needs_review": true, "html": "<p>Напиши, согласен ты или нет с каждым утверждением, и объясни почему — с союзом <b>because</b>.</p><ol><li>Everybody loves pizza.</li><li>Everybody hates tests.</li><li>Girls don't want to be pilots.</li><li>Kids don't like climbing.</li></ol>"}$blk$::jsonb, 5);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'speaking', $blk${"title": "SPEAKING 🎤 Ответь вслух и запиши ответ", "needs_review": true, "html": "<p>Друг говорит тебе четыре фразы. Согласись с двумя и не согласись с двумя, каждый раз объясняя почему.</p><ol><li>School starts too early.</li><li>Winter is better than summer.</li><li>Homework is useful.</li><li>Films are better than books.</li></ol>", "sample": "", "sample_tts": {"text": "I don't think so.", "voice": "en_GB-alba"}}$blk$::jsonb, 6);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'text', $blk${"html": "<p><img src=\"https://classroom.wowteach.ru/media/shared/gg/bye_thumb.webp\" alt=\"\" style=\"height:200px\"></p><p>Спорить по-английски вежливо — тоже навык.</p>"}$blk$::jsonb, 7);
end $$;

do $$
declare v_lesson uuid;
begin
  select id into v_lesson from classroom_lessons
   where unit_id = '028f1e92-6608-40c6-befc-4395319ab6ea' and title = 'Homework 5';
  if v_lesson is null then
    insert into classroom_lessons (unit_id, title, sort_order, kind, is_published)
    values ('028f1e92-6608-40c6-befc-4395319ab6ea', 'Homework 5', 4, 'homework', false) returning id into v_lesson;
  else
    update classroom_lessons set sort_order = 4, kind = 'homework' where id = v_lesson;
    delete from classroom_blocks where lesson_id = v_lesson;
  end if;
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'text', $blk${"html": "<p><img src=\"https://classroom.wowteach.ru/media/shared/gg/hello_girl_wave.webp\" alt=\"\" style=\"height:200px\"></p><h2>Unit 8 · Reading</h2><p>Сегодня читаем рассказ-победитель школьного конкурса — про вежливость.</p>"}$blk$::jsonb, 0);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'text', $blk${"html": "<h3>A short story competition! <span style=\"color:#888\">by Paula Maple, Class B</span></h3><p>Fay was a polite girl. She waited her turn, she asked for permission to do things and she was never late.</p><p>One summer, Fay's cousin, Julie, was visiting her. Julie lived abroad and this was her first trip to England in five years.</p><p>On the first day of the visit, Fay got up at eight o'clock. She waited for Julie to get up. They wanted to meet their grandparents for lunch at one o'clock. But Julie got up at 12.45 p.m. They were late for lunch.</p><p>'Sorry,' Fay said to her grandma. 'Julie got up late.'</p><p>'Maybe she's tired from the trip,' said Grandma.</p><p>At home, Julie took Fay's MP3 player. She didn't ask for permission. She didn't wait her turn when they were playing computer games. And then she didn't come to dinner on time.</p><p>'Listen Julie. I want to …' Fay started to say.</p><p>'Be quiet. I'm watching TV,' said Julie.</p><p>'Listen Julie!' said Fay. 'In my house we are polite, we aren't late, we don't interrupt, we don't take people's things and we wait our turn. In my family we have good manners!'</p><p>Julie was very surprised. For the rest of the visit, Julie was very polite.</p>"}$blk$::jsonb, 1);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'gaps', $blk${"title": "Перетащи слова в пропуски: interrupt · late · permission · polite · time · turn", "mode": "drag", "text": "I hope Larry arrives on __time__. The train will be here soon.\nDon't __interrupt__ when your mum is speaking.\nPlease don't be __late__ for the film. It starts at 7 p.m.\n'I want to play now.' 'You have to wait your __turn__!'\nYou must ask for __permission__ to leave the classroom.\nIt's important for shop assistants to be __polite__ and helpful."}$blk$::jsonb, 2);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'quiz', $blk${"title": "Прочитай объявление о конкурсе и выбери правильное слово", "questions": [{"q": "___ you think good manners are important?", "type": "single", "correct": [0], "options": [{"text": "Do"}, {"text": "Are"}]}, {"q": "___ you got great imagination?", "type": "single", "correct": [0], "options": [{"text": "Have"}, {"text": "Do"}]}, {"q": "___ you good at writing?", "type": "single", "correct": [1], "options": [{"text": "Do"}, {"text": "Are"}]}, {"q": "___ you draw pictures?", "type": "single", "correct": [0], "options": [{"text": "Can"}, {"text": "Are"}]}]}$blk$::jsonb, 3);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'quiz', $blk${"title": "Прочитай рассказ и выбери правильный ответ", "questions": [{"q": "Какой заголовок подходит рассказу лучше всего?", "type": "single", "correct": [2], "options": [{"text": "Late for lunch"}, {"text": "Good family"}, {"text": "Cousin problems"}]}, {"q": "Where did Julie live?", "type": "single", "correct": [0], "options": [{"text": "abroad"}, {"text": "in England"}, {"text": "in the same town as Fay"}]}, {"q": "What time did Fay get up on the first day?", "type": "single", "correct": [0], "options": [{"text": "at eight o'clock"}, {"text": "at 12.45 p.m."}, {"text": "at one o'clock"}]}, {"q": "What did Julie take from Fay?", "type": "single", "correct": [0], "options": [{"text": "her MP3 player"}, {"text": "her computer game"}, {"text": "her phone"}]}, {"q": "Why did Julie tell Fay to be quiet?", "type": "single", "correct": [0], "options": [{"text": "Because she was watching TV."}, {"text": "Because she was sleeping."}, {"text": "Because she was having dinner."}]}, {"q": "What does Fay's family have?", "type": "single", "correct": [0], "options": [{"text": "good manners"}, {"text": "a big house"}, {"text": "lots of money"}]}], "material": "<h3>A short story competition! <span style=\"color:#888\">by Paula Maple, Class B</span></h3><p>Fay was a polite girl. She waited her turn, she asked for permission to do things and she was never late.</p><p>One summer, Fay's cousin, Julie, was visiting her. Julie lived abroad and this was her first trip to England in five years.</p><p>On the first day of the visit, Fay got up at eight o'clock. She waited for Julie to get up. They wanted to meet their grandparents for lunch at one o'clock. But Julie got up at 12.45 p.m. They were late for lunch.</p><p>'Sorry,' Fay said to her grandma. 'Julie got up late.'</p><p>'Maybe she's tired from the trip,' said Grandma.</p><p>At home, Julie took Fay's MP3 player. She didn't ask for permission. She didn't wait her turn when they were playing computer games. And then she didn't come to dinner on time.</p><p>'Listen Julie. I want to …' Fay started to say.</p><p>'Be quiet. I'm watching TV,' said Julie.</p><p>'Listen Julie!' said Fay. 'In my house we are polite, we aren't late, we don't interrupt, we don't take people's things and we wait our turn. In my family we have good manners!'</p><p>Julie was very surprised. For the rest of the visit, Julie was very polite.</p>"}$blk$::jsonb, 4);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'gaps', $blk${"title": "Прочитай рассказ ещё раз и впиши по одному слову", "mode": "type", "text": "Fay was a __polite__ girl.\nShe __waited__ her turn.\nShe asked for __permission__ to do things.\nShe was never __late__.\nJulie and Fay were late for __lunch__ with their grandparents.\nJulie __didn't__ wait her turn when they were playing video games.\nJulie didn't arrive on time for __dinner__.\nAfter Fay spoke to her, Julie was __polite__ for the rest of the visit.", "material": "<h3>A short story competition! <span style=\"color:#888\">by Paula Maple, Class B</span></h3><p>Fay was a polite girl. She waited her turn, she asked for permission to do things and she was never late.</p><p>One summer, Fay's cousin, Julie, was visiting her. Julie lived abroad and this was her first trip to England in five years.</p><p>On the first day of the visit, Fay got up at eight o'clock. She waited for Julie to get up. They wanted to meet their grandparents for lunch at one o'clock. But Julie got up at 12.45 p.m. They were late for lunch.</p><p>'Sorry,' Fay said to her grandma. 'Julie got up late.'</p><p>'Maybe she's tired from the trip,' said Grandma.</p><p>At home, Julie took Fay's MP3 player. She didn't ask for permission. She didn't wait her turn when they were playing computer games. And then she didn't come to dinner on time.</p><p>'Listen Julie. I want to …' Fay started to say.</p><p>'Be quiet. I'm watching TV,' said Julie.</p><p>'Listen Julie!' said Fay. 'In my house we are polite, we aren't late, we don't interrupt, we don't take people's things and we wait our turn. In my family we have good manners!'</p><p>Julie was very surprised. For the rest of the visit, Julie was very polite.</p>"}$blk$::jsonb, 5);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'task', $blk${"title": "WRITING ✍️ Напиши свой короткий рассказ на конкурс", "needs_review": true, "html": "<p>Тема конкурса — почему быть вежливым это хорошая мысль. Напиши рассказ из шести-восьми предложений в прошедшем времени.</p><p>Слова-помощники: polite, interrupt, wait your turn, ask for permission, late, good manners.</p>"}$blk$::jsonb, 6);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'text', $blk${"html": "<p><img src=\"https://classroom.wowteach.ru/media/shared/gg/bye_popper.webp\" alt=\"\" style=\"height:200px\"></p><p>Рассказ прочитан, свой написан.</p>"}$blk$::jsonb, 7);
end $$;

do $$
declare v_lesson uuid;
begin
  select id into v_lesson from classroom_lessons
   where unit_id = '028f1e92-6608-40c6-befc-4395319ab6ea' and title = 'Homework 6';
  if v_lesson is null then
    insert into classroom_lessons (unit_id, title, sort_order, kind, is_published)
    values ('028f1e92-6608-40c6-befc-4395319ab6ea', 'Homework 6', 5, 'homework', false) returning id into v_lesson;
  else
    update classroom_lessons set sort_order = 5, kind = 'homework' where id = v_lesson;
    delete from classroom_blocks where lesson_id = v_lesson;
  end if;
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'text', $blk${"html": "<p><img src=\"https://classroom.wowteach.ru/media/shared/gg/hello_highfive.webp\" alt=\"\" style=\"height:200px\"></p><h2>Unit 8 · Listening and Writing</h2><p>Сегодня слушаем спор о будущем и пишем своё сочинение.</p>"}$blk$::jsonb, 0);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'order', $blk${"title": "Составь предсказания о будущем мира", "items": [{"words": ["We", "will", "all", "read", "e-books."], "sentence": "We will all read e-books.", "prompt": "все будут читать электронные книги"}, {"words": ["The", "weather", "will", "be", "hotter."], "sentence": "The weather will be hotter.", "prompt": "погода станет жарче"}, {"words": ["Cars", "will", "be", "cleaner", "for", "the", "environment."], "sentence": "Cars will be cleaner for the environment.", "prompt": "машины станут чище для природы"}, {"words": ["The", "weekend", "will", "be", "from", "Thursday", "to", "Sunday."], "sentence": "The weekend will be from Thursday to Sunday.", "prompt": "выходные будут с четверга по воскресенье"}]}$blk$::jsonb, 1);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'quiz', $blk${"title": "LISTENING 🎧 Послушай разговор Фрэнка и Зены и выбери правильный ответ", "audio": "https://api.wowteach.ru/storage/v1/object/public/classroom-media/gg3%20wb/GG%20L3%20WkBk%20A20.mp3", "skill": "listening", "questions": [{"q": "___ books will be on tablets.", "type": "single", "correct": [0], "options": [{"text": "School"}, {"text": "All"}]}, {"q": "Animals will have problems because of the ___.", "type": "single", "correct": [0], "options": [{"text": "weather"}, {"text": "people"}]}, {"q": "There will be ___ snow where the polar bears live.", "type": "single", "correct": [1], "options": [{"text": "more"}, {"text": "no"}]}, {"q": "Cars ___ work with electricity.", "type": "single", "correct": [1], "options": [{"text": "won't"}, {"text": "will"}]}, {"q": "There will be more ___ for kids.", "type": "single", "correct": [1], "options": [{"text": "gardens"}, {"text": "playgrounds"}]}, {"q": "We'll work ___ days a week.", "type": "single", "correct": [1], "options": [{"text": "four"}, {"text": "three"}]}]}$blk$::jsonb, 2);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'gaps', $blk${"title": "LISTENING 🎧 Послушай разговор ещё раз и впиши по одному слову", "audio": "https://api.wowteach.ru/storage/v1/object/public/classroom-media/gg3%20wb/GG%20L3%20WkBk%20A20.mp3", "skill": "listening", "mode": "type", "text": "We won't have books anymore. We will all read __e-books__. Our school books will be on __tablets__.\nI think the weather will be __hotter__ and there won't be any __snow__ where the polar bears live.\nI think the environment will be __cleaner__ because most cars will work with __electricity__.\nThere will be nice __gardens__ next to the flats and more playgrounds for kids.\nI think we will work __three__ days a week. The weekend will be from __Thursday__ to Sunday."}$blk$::jsonb, 3);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'quiz', $blk${"title": "Прочитай сочинение Тони о домах будущего и выбери правильный вариант", "questions": [{"q": "I'm ___ houses in fifty years from now will be different.", "type": "single", "correct": [0], "options": [{"text": "sure"}, {"text": "think"}]}, {"q": "Some people think we will all live in blocks of flats in cities, but I ___ think this will happen.", "type": "single", "correct": [0], "options": [{"text": "don't"}, {"text": "won't"}]}, {"q": "I ___ lots of people will move to the country.", "type": "single", "correct": [1], "options": [{"text": "sure"}, {"text": "think"}]}, {"q": "___ there will be faster trains from the villages.", "type": "single", "correct": [0], "options": [{"text": "Maybe"}, {"text": "Hope"}]}, {"q": "I ___ more people will grow fruit and vegetables in their gardens to help nature.", "type": "single", "correct": [1], "options": [{"text": "will"}, {"text": "hope"}]}], "material": "<h3>Houses in the future <span style=\"color:#888\">by Tony Watson</span></h3><p>I'm sure houses in fifty years from now will be different. Some people think we will all live in blocks of flats in cities, but I don't think this will happen. I think lots of people will move to the country. Maybe there will be faster trains from the villages that people will take to go to work in the cities. Houses will be detached or semi-detached. I hope more people will grow fruit and vegetables in their gardens to help nature. I think people will go hiking and ride their bikes more to spend time close to nature.</p>"}$blk$::jsonb, 4);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'task', $blk${"title": "WRITING ✍️ Напиши сочинение «Школа через пятьдесят лет»", "needs_review": true, "html": "<p>Начни так: <i>I think schools in fifty years from now …</i> — и напиши восемь-десять предложений.</p><p>Сначала выбери, о чём будешь писать:</p><ul><li><b>School items:</b> tablets / books / computers / e-books</li><li><b>Where:</b> home / school building / online lessons</li><li><b>Students:</b> lots of students / not a lot of students / teachers</li><li><b>What:</b> more subjects / not a lot of subjects / exams / no exams</li><li><b>How often:</b> every week / every day / at weekends / three days a week</li><li><b>Classroom:</b> small or big / computer studies rooms / gym / playground / library</li><li><b>School trips:</b> abroad / the country / city</li><li><b>School lunches:</b> meals / sandwiches / free / expensive</li></ul><p>Используй фразы предсказаний: <b>I think …</b>, <b>I don’t think …</b>, <b>I’m sure …</b>, <b>I hope …</b>, <b>Maybe …</b></p>"}$blk$::jsonb, 5);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'text', $blk${"html": "<p><img src=\"https://classroom.wowteach.ru/media/shared/gg/bye_certificate.webp\" alt=\"\" style=\"height:200px\"></p><p>И послушали, и сочинение о будущем написали.</p>"}$blk$::jsonb, 6);
end $$;

do $$
declare v_lesson uuid;
begin
  select id into v_lesson from classroom_lessons
   where unit_id = '028f1e92-6608-40c6-befc-4395319ab6ea' and title = 'Homework 7';
  if v_lesson is null then
    insert into classroom_lessons (unit_id, title, sort_order, kind, is_published)
    values ('028f1e92-6608-40c6-befc-4395319ab6ea', 'Homework 7', 6, 'homework', false) returning id into v_lesson;
  else
    update classroom_lessons set sort_order = 6, kind = 'homework' where id = v_lesson;
    delete from classroom_blocks where lesson_id = v_lesson;
  end if;
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'text', $blk${"html": "<p><img src=\"https://classroom.wowteach.ru/media/shared/gg/hello_teen_wave.webp\" alt=\"\" style=\"height:200px\"></p><h2>Unit 8 · Check yourself!</h2><p>Повторяем весь юнит перед тестом.</p>"}$blk$::jsonb, 0);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'quiz', $blk${"title": "Выбери правильное слово", "questions": [{"q": "One day I want to ___ rich.", "type": "single", "correct": [0], "options": [{"text": "be"}, {"text": "have"}]}, {"q": "Will you ___ a foreign language next year at school?", "type": "single", "correct": [0], "options": [{"text": "learn"}, {"text": "live"}]}, {"q": "Would you like to live ___ your own?", "type": "single", "correct": [0], "options": [{"text": "on"}, {"text": "in"}]}, {"q": "I want to ___ an interesting job.", "type": "single", "correct": [1], "options": [{"text": "be"}, {"text": "have"}]}, {"q": "When Dad was a student he ___ abroad.", "type": "single", "correct": [1], "options": [{"text": "had"}, {"text": "lived"}]}, {"q": "Mum wanted to be ___ when she was younger.", "type": "single", "correct": [0], "options": [{"text": "famous"}, {"text": "doctor"}]}]}$blk$::jsonb, 1);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'exact_input', $blk${"title": "Посмотри на подсказку и напиши пропущенное слово по-английски", "items": [{"prompt": "Who did you ___ to the party? (пригласить)", "accept": ["invite", "Invite"]}, {"prompt": "Come here and give me a ___! (объятие)", "accept": ["hug", "a hug", "Hug"]}, {"prompt": "Grandma likes to ___ all her grandchildren. (целовать)", "accept": ["kiss", "Kiss"]}, {"prompt": "I'll ___ you on the phone later. (позвонить)", "accept": ["call", "Call"]}, {"prompt": "Your brother is playing on the computer now, you need to wait your ___. (очередь)", "accept": ["turn", "Turn"]}, {"prompt": "When you want to use Dad's tablet, ask him ___. (разрешение)", "accept": ["permission", "for permission", "Permission"]}]}$blk$::jsonb, 2);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'order', $blk${"title": "Составь предложения о будущем: ✔ — утверждение, ✘ — отрицание, ❓ — вопрос", "items": [{"words": ["I'll", "be", "a", "vet", "one", "day."], "sentence": "I'll be a vet one day.", "prompt": "✔ я стану ветеринаром"}, {"words": ["Amanda", "won't", "travel", "by", "plane."], "sentence": "Amanda won't travel by plane.", "prompt": "✘ Аманда не будет летать самолётом"}, {"words": ["Will", "John", "learn", "to", "drive", "when", "he", "is", "eighteen?"], "sentence": "Will John learn to drive when he is eighteen?", "prompt": "❓ Джон научится водить в восемнадцать?"}, {"words": ["What", "will", "Fred", "do", "after", "school?"], "sentence": "What will Fred do after school?", "prompt": "❓ что Фред будет делать после школы?"}, {"words": ["Mary", "will", "be", "rich", "one", "day."], "sentence": "Mary will be rich one day.", "prompt": "✔ Мэри однажды разбогатеет"}, {"words": ["Tina", "won't", "have", "a", "big", "family."], "sentence": "Tina won't have a big family.", "prompt": "✘ у Тины не будет большой семьи"}]}$blk$::jsonb, 3);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'gaps', $blk${"title": "Прочитай ответы и перетащи вопросительные слова в пропуски", "mode": "drag", "text": "A: __What__ is your favourite hobby?\nB: My favourite hobby is chess.\nA: __What__ did you eat in the UK?\nB: I ate fish and chips in the UK.\nA: __Where__ are you going to fly for your next holiday?\nB: We're going to fly to France for our next holiday.\nA: __Who__ made this cake?\nB: Mum made this cake.\nA: __How often__ do you exercise?\nB: I exercise three days a week.\nA: __When__ is the film on TV?\nB: The film is on TV in five minutes."}$blk$::jsonb, 4);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'quiz', $blk${"title": "Прочитай короткие разговоры и выбери правильный ответ", "questions": [{"q": "A: This cake is disgusting!  B: I ___. I don’t like it.", "type": "single", "correct": [0], "options": [{"text": "agree"}, {"text": "don't agree"}]}, {"q": "A: I think John will be late.  B: You’re ___. He’s opening the door now!", "type": "single", "correct": [1], "options": [{"text": "right"}, {"text": "wrong"}]}, {"q": "A: Cars are very bad for cities.  B: ___ Bikes are much better.", "type": "single", "correct": [0], "options": [{"text": "That's what I think too."}, {"text": "No, that's not true."}]}, {"q": "A: This Maths homework will be boring.  B: ___ I enjoy Maths.", "type": "single", "correct": [1], "options": [{"text": "I agree."}, {"text": "I don't think so."}]}, {"q": "A: I think Venice is a beautiful city.  B: ___ I love it there.", "type": "single", "correct": [0], "options": [{"text": "I agree."}, {"text": "I disagree."}]}, {"q": "A: This watch costs $500!  B: ___ Look! It’s $50!", "type": "single", "correct": [0], "options": [{"text": "No, that isn't right!"}, {"text": "That's right!"}]}]}$blk$::jsonb, 5);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'speaking', $blk${"title": "SPEAKING 🎤 Расскажи вслух и запиши ответ", "needs_review": true, "html": "<p>Расскажи, каким ты видишь себя через десять лет: где будешь жить, что будешь делать, чему научишься. Пять-шесть предложений с <b>will</b>.</p>", "sample": "", "sample_tts": {"text": "I think I will live in a big city.", "voice": "en_GB-alba"}}$blk$::jsonb, 6);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'text', $blk${"html": "<p><img src=\"https://classroom.wowteach.ru/media/shared/gg/bye_trophy.webp\" alt=\"\" style=\"height:200px\"></p><p>Юнит пройден. Можно браться за тест.</p>"}$blk$::jsonb, 7);
end $$;
